//! Parity corpus for `summary.rs`. Every `expected` is the output of the real TS, `renderVerdict`
//! of `packages/cli/src/lib/gate/summary.ts`, run on Node v26.13.1 over the log decoded as UTF-8
//! and passed through `toWellFormed()` (Node writes a lone surrogate as U+FFFD):
//!
//! ```text
//! node --experimental-strip-types gen.mjs   # gen.mjs imports renderVerdict and prints each case
//! ```
//!
//! The `log` bytes are decoded with `String::from_utf8_lossy`, which replaces invalid UTF-8 the way
//! Node's decoder does. Cases `h6*` are the divergence classes the design review (H6) named.

use super::{render_verdict, sentinel_line};

struct Case {
    name: &'static str,
    kind: &'static str,
    exit: i32,
    path: &'static str,
    log: &'static [u8],
    expected: &'static str,
}

#[test]
fn matches_node_on_the_corpus() {
    let mut failures = Vec::new();
    for case in CORPUS {
        let log = String::from_utf8_lossy(case.log);
        let got = render_verdict(case.kind, case.exit, case.path, &log);
        if got != case.expected {
            failures.push(format!(
                "{}:\n  want {:?}\n  got  {:?}",
                case.name, case.expected, got
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn corpus_exercises_truncation_and_both_caps() {
    let truncated = CORPUS
        .iter()
        .filter(|c| c.expected.contains("[truncated]"))
        .count();
    assert!(truncated >= 5, "only {truncated} truncated cases");
    assert!(
        CORPUS
            .iter()
            .any(|c| c.exit == 0 && c.expected.len() > 1500)
    );
    assert!(
        CORPUS
            .iter()
            .any(|c| c.exit != 0 && c.expected.len() > 3000)
    );
}

#[test]
fn sentinel_has_the_documented_shape() {
    assert_eq!(
        sentinel_line("fast", 1, "/l/f.log"),
        "navori gate fast: exit 1 — log /l/f.log"
    );
}

